#include <zephyr/kernel.h>
#include <zephyr/device.h>
#include <zephyr/drivers/firmware/qemu_fwcfg.h>
#include <zephyr/sys/io.h>
#include <zephyr/logging/log.h>

LOG_MODULE_REGISTER(qemu_fwcfg, CONFIG_QEMU_FWCFG_LOG_LEVEL);

/* FWCFG I/O ports */
#define FW_CFG_CTL_PORT 0x510
#define FW_CFG_DATA_PORT 0x511

/* FWCFG items */
#define FW_CFG_SIGNATURE 0x00
#define FW_CFG_SIGNATURE_MAGIC 0x51091186

/*
 * FWCFG control port operations:
 * Write 16-bit selector to FW_CFG_CTL_PORT.
 * Read/write 8/16/32-bit data from/to FW_CFG_DATA_PORT.
 */

static void fwcfg_select(uint16_t selector)
{
    sys_out16(selector, FW_CFG_CTL_PORT);
}

static uint32_t fwcfg_read_u32(void)
{
    return sys_in32(FW_CFG_DATA_PORT);
}

static uint16_t fwcfg_read_u16(void)
{
    return sys_in16(FW_CFG_DATA_PORT);
}

static uint8_t fwcfg_read_u8(void)
{
    return sys_in8(FW_CFG_DATA_PORT);
}

static void fwcfg_read_bytes(void *buf, size_t len)
{
    uint8_t *ptr = (uint8_t *)buf;

    for (size_t i = 0; i < len; i++) {
        ptr[i] = sys_in8(FW_CFG_DATA_PORT);
    }
}

static int qemu_fwcfg_read(const struct device *dev, uint16_t item_id,
                            void *buf, size_t len)
{
    ARG_UNUSED(dev);

    fwcfg_select(item_id);
    fwcfg_read_bytes(buf, len);

    return 0;
}

static int qemu_fwcfg_get_item_size(const struct device *dev, uint16_t item_id,
                                     size_t *size)
{
    ARG_UNUSED(dev);

    /* Select the item and read its size (4 bytes) */
    fwcfg_select(item_id | 0x8000); /* Set bit 15 to read size */
    *size = fwcfg_read_u32();

    return 0;
}

static int qemu_fwcfg_init(const struct device *dev)
{
    uint32_t signature;

    /* Check for FWCFG device presence by reading its signature */
    fwcfg_select(FW_CFG_SIGNATURE);
    signature = fwcfg_read_u32();

    if (signature != FW_CFG_SIGNATURE_MAGIC) {
        LOG_ERR("QEMU FWCFG signature mismatch: 0x%x (expected 0x%x)",
                signature, FW_CFG_SIGNATURE_MAGIC);
        return -ENODEV; /* Device not found or not properly initialized */
    }

    LOG_DBG("QEMU FWCFG device found with signature 0x%x", signature);

    return 0;
}

static const struct qemu_fwcfg_api qemu_fwcfg_api = {
    .read = qemu_fwcfg_read,
    .get_item_size = qemu_fwcfg_get_item_size,
};

/*
 * The FWCFG device is typically a single instance.
 * It's defined in the devicetree as 'fwcfg@510'.
 */
DEVICE_DT_DEFINE(DT_NODELABEL(fwcfg), qemu_fwcfg_init, NULL,
                 NULL, NULL, POST_KERNEL,
                 CONFIG_KERNEL_INIT_PRIORITY_DEFAULT,
                 &qemu_fwcfg_api);
